# Apply the cleanest transformation logic we developed - flood_fill_intruders approach
from collections import deque

def apply_final_transformation(input_grid):
    """Clean intruders within connected regions using flood-fill"""
    rows, cols = len(input_grid), len(input_grid[0])

    # Make a copy for output
    result = [[input_grid[r][c] for c in range(cols)] for r in range(rows)]

    # Find all components (using 8-connectivity for regions)
    visited = set()
    components = {}  # component_id -> list of cell coords

    for r in range(rows):
        for c in range(cols):
            if input_grid[r][c] == 1:  # Skip background
                continue
            if (r, c) in visited:
                continue

            color = input_grid[r][c]
            component = []
            q = deque([(r, c)])

            while q:
                curr_r, curr_c = q.popleft()
                if (curr_r, curr_c) in visited:
                    continue

                visited.add((curr_r, curr_c))
                component.append((curr_r, curr_c))

                # Add 8 neighbors
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if input_grid[nr][nc] == color and (nr, nc) not in visited:
                                q.append((nr, nc))

            comp_id = (color, id(component))
            components[comp_id] = component

    # For each non-background component, determine dominant color and fix intruders
    for comp_id, cells in components.items():
        color = comp_id[0]  # Primary color of this component

        # Count dominant vs minority pixels in the original grid for these positions
        dominant_count = sum(1 for cr, cc in cells if input_grid[cr][cc] == color)

        if dominant_count < len(cells) / 2:
            # More than half are intruders - the whole block is noisy
            # Replace entire block with a single color
            # Check surroundings for context
            neighbors_8 = [(cr + dr, cc + dc) for cr, cc in cells 
                         for dr in [-1, 0, 1] for dc in [-1, 0, 1] 
                         if dr != 0 or dc != 0]

            neighbor_colors = {}
            for nr, nc in neighbors_8:
                if 0 <= nr < rows and 0 <= nc < cols:
                    val = input_grid[nr][nc]
                    if val != 1:  # Not background
                        neighbor_colors[val] = neighbor_colors.get(val, 0) + 1

            if neighbor_colors:
                best_color = max(neighbor_colors.keys(), key=lambda x: neighbor_colors[x])
            else:
                best_color = color
            for cr, cc in cells:
                result[cr][cc] = best_color
        else:
            # Component has majority of its primary color - fix only intruders
            for cr, cc in cells:
                if input_grid[cr][cc] != color:
                    # This is an intruder - replace with dominant color
                    result[cr][cc] = color

    return result

